/**
 * Writing the studio's autogenerated commit message for one graph change.
 *
 * A commit message is one short string, so the call is a plain-text completion
 * rather than a function-tool round-trip: function tools combined with a
 * reasoning effort are rejected for the gpt-5 family on the OpenAI-compatible
 * chat-completions proxy these calls go through.
 * specs/model-providers/missing-model-popup.feature.
 */

import { featureByKey } from "@langwatch/model-provider-contract";
import { generateText } from "ai";
import { createPatch } from "diff";

import type {
  WorkflowAiCall,
  WorkflowCommitMessageModel,
} from "../app/workflow.app.ts";
import {
  WORKFLOW_COMMIT_MESSAGE_FEATURE_KEY,
  WORKFLOW_COMMIT_MESSAGE_PATCH_FILE,
  WORKFLOW_COMMIT_MESSAGE_PATCH_LABELS,
  workflowCommitMessagePrompt,
} from "../rules/workflow-commit-message.rules.ts";

export class WorkflowCommitMessageService {
  static create(options: {
    models: WorkflowCommitMessageModel;
    aiCalls: WorkflowAiCall;
  }): WorkflowCommitMessageService {
    return new WorkflowCommitMessageService(options);
  }

  private constructor(
    private readonly options: {
      models: WorkflowCommitMessageModel;
      aiCalls: WorkflowAiCall;
    },
  ) {}

  /**
   * The message for the change between two already-normalised graphs. The
   * caller decides they differ; this one only describes how.
   */
  async generate(input: {
    projectId: string;
    previousDsl: string;
    nextDsl: string;
  }): Promise<string> {
    const feature = featureByKey(WORKFLOW_COMMIT_MESSAGE_FEATURE_KEY);
    // A missing registry entry is a build-time mistake in the process that
    // composed this service, not a cause a customer can act on, so it stays an
    // ordinary error and degrades to an unknown failure carrying a trace id.
    if (!feature) {
      throw new Error(`${WORKFLOW_COMMIT_MESSAGE_FEATURE_KEY} feature is not registered`);
    }

    const prompt = workflowCommitMessagePrompt({
      previousDsl: input.previousDsl,
      diff: createPatch(
        WORKFLOW_COMMIT_MESSAGE_PATCH_FILE,
        input.previousDsl,
        input.nextDsl,
        WORKFLOW_COMMIT_MESSAGE_PATCH_LABELS.previous,
        WORKFLOW_COMMIT_MESSAGE_PATCH_LABELS.next,
      ),
    });

    // A model this project cannot resolve refuses on its own terms, and that
    // refusal has its own toast; everything else the provider does becomes the
    // typed `ai_call_failed` the studio renders as a configuration hint.
    const model = await this.options.models.resolve({
      projectId: input.projectId,
      featureKey: WORKFLOW_COMMIT_MESSAGE_FEATURE_KEY,
    });

    const completion = await this.options.aiCalls.run(feature, () =>
      generateText({
        model,
        providerOptions: { openai: { reasoningEffort: "low" } },
        messages: [
          { role: "system", content: prompt.system },
          { role: "user", content: prompt.user },
        ],
      }),
    );

    return completion.text.trim();
  }
}
